];

// Recibe los items agrupados por ruta del nodo Summarize.
// Construye el mensaje de resumen diario.
const items = $input.all();
const fecha = new Date().toISOString().slice(0, 10);

let totalSolicitudes = 0;
let totalMonto = 0;
let aprobacion = { cantidad: 0, monto: 0 };
let rechazo = { cantidad: 0, monto: 0 };
let revision = { cantidad: 0, monto: 0 };
let invalido = { cantidad: 0, monto: 0 };

for (const item of items) {
  const r = item.json;
  totalSolicitudes += r.cantidad || 0;
  totalMonto += r.monto_total || 0;
  if (r.ruta === 'APROBACION') { aprobacion.cantidad = r.cantidad; aprobacion.monto = r.monto_total; }
  else if (r.ruta === 'RECHAZO') { rechazo.cantidad = r.cantidad; rechazo.monto = r.monto_total; }
  else if (r.ruta === 'REVISION') { revision.cantidad = r.cantidad; revision.monto = r.monto_total; }
  else if (r.ruta === 'DATOS_INVALIDOS') { invalido.cantidad = r.cantidad; invalido.monto = r.monto_total; }
}

const tasa = totalSolicitudes > 0
  ? ((aprobacion.cantidad / totalSolicitudes) * 100).toFixed(1)
  : '0.0';

const formatCLP = n => `$${Number(n).toLocaleString('es-CL')}`;

const mensaje = [
  `=== RESUMEN DIARIO AndesHogar SpA — ${fecha} ===`,
  `Total solicitudes procesadas: ${totalSolicitudes}`,
  `Monto total del dia: ${formatCLP(totalMonto)}`,
  ``,
  `APROBACION : ${aprobacion.cantidad} solicitudes — ${formatCLP(aprobacion.monto)}`,
  `REVISION   : ${revision.cantidad} solicitudes — ${formatCLP(revision.monto)}`,
  `RECHAZO    : ${rechazo.cantidad} solicitudes — ${formatCLP(rechazo.monto)}`,
  `INVALIDAS  : ${invalido.cantidad} solicitudes — ${formatCLP(invalido.monto)}`,
  ``,
  `Tasa de aprobacion automatica: ${tasa}%`,
].join('\n');

return [{ json: { mensaje, fecha, totalSolicitudes, totalMonto, tasa } }];
